```javascript
function debounce(fn, ms) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), ms);
  };
}
```

**Usage:**
```javascript
const handleResize = debounce(() => {
  console.log('Resized!');
}, 300);

window.addEventListener('resize', handleResize);
```

