from abc import ABC, abstractmethod
from typing import Generic, TypeVar, Optional

T = TypeVar("T")

class StorageBackend(ABC, Generic[T]):
    @abstractmethod
    def get(self, key: str) -> Optional[T]:
        """Retrieve value by key. Returns None if not found."""
        ...

    @abstractmethod
    def put(self, key: str, value: T) -> None:
        """Store value at key. Overwrites if key exists."""
        ...

    @abstractmethod
    def delete(self, key: str) -> bool:
        """Delete key. Returns True if key existed."""
        ...


# --- Example implementation ---
class InMemoryStorage(StorageBackend[str]):
    def __init__(self) -> None:
        self._data: dict[str, str] = {}

    def get(self, key: str) -> Optional[str]:
        return self._data.get(key)

    def put(self, key: str, value: str) -> None:
        self._data[key] = value

    def delete(self, key: str) -> bool:
        if key in self._data:
            del self._data[key]
            return True
        return False


# --- Usage ---
if __name__ == "__main__":
    store: StorageBackend[str] = InMemoryStorage()
    store.put("greeting", "hello")
    print(store.get("greeting"))   # hello
    print(store.delete("greeting"))# True
    print(store.get("greeting"))   # None
```

```go
package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"sync"
)

type Result struct {
	URL  string
	Body string
	Err  error
}

func FetchAll(ctx context.Context, urls []string) []Result {
	var wg sync.WaitGroup
	results := make(chan Result, len(urls))

	for _, url := range urls {
		wg.Add(1)
		go func(u string) {
			defer wg.Done()

			req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
			if err != nil {
				results <- Result{URL: u, Err: err}
				return
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				results <- Result{URL: u, Err: err}
				return
			}
			defer resp.Body.Close()

			body, err := io.ReadAll(resp.Body)
			if err != nil {
				results <- Result{URL: u, Err: err}
				return
			}

			results <- Result{URL: u, Body: string(body)}
		}(url)
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	var out []Result
	for r := range results {
		out = append(out, r)
	}
	return out
}

func main() {
	urls := []string{
		"https://httpbin.org/get",
		"https://httpbin.org/uuid",
		"https://httpbin.org/user-agent",
	}

	results := FetchAll(context.Background(), urls)
	for _, r := range results {
		if r.Err != nil {
			fmt.Printf("%s: error: %v\n", r.URL, r.Err)
		} else {
			fmt.Printf("%s: %d bytes\n", r.URL, len(r.Body))
		}
	}
}
```

**Key points:**
- Uses `context.Context` for cancellation/timeout control
- `sync.WaitGroup` + channel for fan-out/fan-in
- `http.NewRequestWithContext` binds the context to each request
- Errors are returned per-URL so one failure doesn't block others
- Bounded channel (`len(urls)`) prevents goroutine leaks

Here is a concise, idiomatic Go function using `errgroup` for concurrency control and error propagation. It preserves the input order in the returned slice.

```go
package main

import (
	"context"
	"io"
	"net/http"
	"sync"

	"golang.org/x/sync/errgroup"
)

// FetchAll concurrently fetches URLs and returns bodies in the same order.
// It returns an error if any request fails (non-2xx or transport error).
func FetchAll(ctx context.Context, urls []string) ([][]byte, error) {
	g, ctx := errgroup.WithContext(ctx)

	// Limit concurrency to avoid overwhelming the system/target
	g.SetLimit(10) 

	bodies := make([][]byte, len(urls))
	var mu sync.Mutex // Protects bodies slice if SetLimit > 1 (errgroup handles this internally for Go 1.23+, but safe for older)

	for i, url := range urls {
		i, url := i, url // capture loop variables
		g.Go(func() error {
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
			if err != nil {
				return err
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if resp.StatusCode < 200 || resp.StatusCode >= 300 {
				return &fetchError{URL: url, Status: resp.StatusCode}
			}

			body, err := io.ReadAll(resp.Body)
			if err != nil {
				return err
			}

			mu.Lock()
			bodies[i] = body
			mu.Unlock()
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		return nil, err
	}
	return bodies, nil
}

type fetchError struct {
	URL    string
	Status int
}

func (e *fetchError) Error() string {
	return "fetch failed: " + e.URL + " status " + string(rune(e.Status))
}
```

### Key Details
1.  **`errgroup.WithContext`**: Cancels all in-flight requests immediately if one fails.
2.  **`g.SetLimit(10)`**: Caps concurrent goroutines (prevents file descriptor exhaustion).
3.  **Order Preservation**: Pre-allocates `bodies` slice and writes to index `i`.
4.  **Context Propagation**: Passes `ctx` to `http.NewRequestWithContext` so cancellation works mid-request.
5.  **Error Type**: Custom `fetchError` distinguishes HTTP errors from network errors.

### Usage
```go
func main() {
	ctx := context.Background()
	urls := []string{
		"https://example.com",
		"https://golang.org",
		"https://httpbin.org/status/404", // Will cause an error
	}

	bodies, err := FetchAll(ctx, urls)
	if err != nil {
		log.Fatal(err)
	}
	for i, body := range bodies {
		fmt.Printf("URL %d: %d bytes\n", i, len(body))
	}
}
```

```javascript
function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

// Example
const log = debounce((msg) => console.log(msg), 300);

log('a');
log('b');
log('c'); // Only "c" logs after 300ms of silence
```

